    vouched.dueDate = invoice.dueDate;
  }
  if (invoice.number) {
    vouched.number = invoice.number;
  }
  if (invoice.payments) {
    vouched.payments = invoice.payments.map((p) => ({ ...p }));
  }

  return ok(vouched);
}

